/** @module cli/completions/fish */

export function generateFish() {
  return `# fish completion for pix-galaxy-mcp
# Generated by pix-galaxy-mcp completions
# Install: pix-galaxy-mcp completions --shell fish > ~/.config/fish/completions/pix-galaxy-mcp.fish

complete -c pix-galaxy-mcp -f

# Commands
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a serve     -d "Start MCP server"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a up        -d "Serve over SSE (HTTP daemon)"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a daemon    -d "Manage background daemon"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a install   -d "Install into agent/IDE"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a uninstall -d "Remove from agent/IDE"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a setup -d "Install/uninstall wizard"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a config    -d "Print mcp.json snippet"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a tools     -d "List or call MCP tools"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a doctor    -d "System health check"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a skills    -d "Manage skills"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a adr       -d "Architecture Decision Records"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a handoff   -d "LLM context handoff"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a handon    -d "Verify the last handoff"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a fix       -d "Auto-fix project file tree"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a stats     -d "Show telemetry statistics"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a cache     -d "Inspect the on-disk tool cache"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a roles     -d "Manage review persona roles"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a guard     -d "Permission-guard processor"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a update    -d "Self-update from upstream"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a agent-commands -d "Manage agent slash commands"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a completions -d "Generate shell completion"
complete -c pix-galaxy-mcp -n "__fish_use_subcommand" -a help      -d "Show help"

# Daemon actions
complete -c pix-galaxy-mcp -n "__fish_seen_subcommand_from daemon" -a "start stop status logs" -f

# Tools subcommands
complete -c pix-galaxy-mcp -n "__fish_seen_subcommand_from tools" -a "list call" -f

# Skills actions
complete -c pix-galaxy-mcp -n "__fish_seen_subcommand_from skills" -a "reload" -f

# ADR actions
complete -c pix-galaxy-mcp -n "__fish_seen_subcommand_from adr" -a "new" -f

# Global options
complete -c pix-galaxy-mcp -l help -s h -d "Show help"
complete -c pix-galaxy-mcp -l transport -x -a "stdio sse" -d "Transport type"
complete -c pix-galaxy-mcp -l agent -x -a "claude codex cursor copilot gemini cline roo zed opencode antigravity devin kilo kimi vibe grok droid kiro qwen pi vscode jetbrains neovim emacs" -d "Agent name"
complete -c pix-galaxy-mcp -l format -x -a "full brief minimal" -d "Handoff format"
complete -c pix-galaxy-mcp -l status -x -a "proposed accepted deprecated superseded" -d "ADR status"
complete -c pix-galaxy-mcp -l shell -x -a "zsh bash fish" -d "Shell type"
complete -c pix-galaxy-mcp -l global -d "Use global install"
complete -c pix-galaxy-mcp -l dry-run -d "Preview without applying"
complete -c pix-galaxy-mcp -l force -d "Override existing config"
complete -c pix-galaxy-mcp -l compress -d "Compress handoff output"
complete -c pix-galaxy-mcp -l telemetry -d "Include telemetry"
`;
}
